// Transcribed from @solidjs/web@2.0.0-rc.9 `types/index.d.ts`.
//
// Byte-faithful, because every claim in `expected.json` rests on them:
//
// - `ValidComponent`, `ComponentProps`   `:47-48`
// - `DynamicOptions` and `dynamic`       `:82-97`
//
// Reduced: doc comments are dropped, and `IntrinsicElement` (`:46`) is
// `string` rather than the keys of the full `JSX.IntrinsicElements` table,
// which this fixture never names. Every `ValidComponent` the real union admits
// is still admitted, and no argument written here depends on the narrowing.

import type { Component } from "solid-js";

declare namespace JSX {
  interface IntrinsicElements {
    [name: string]: Record<string, unknown>;
  }
}

export type IntrinsicElement = Extract<keyof JSX.IntrinsicElements, string>;
export type ValidComponent = IntrinsicElement | Component<any> | (string & {});
export type ComponentProps<T extends ValidComponent> = T extends Component<infer P> ? P : T extends keyof JSX.IntrinsicElements ? JSX.IntrinsicElements[T] : Record<string, unknown>;
export interface DynamicOptions {
    deferStream?: boolean;
    static?: boolean;
}
export declare function dynamic<T extends ValidComponent>(source: () => T | Promise<T> | null | undefined | false, options?: DynamicOptions): Component<ComponentProps<T>>;
